class BenefitEligibilityDecision(str, Enum):
    APLICA = "APLICA"
    NO_APLICA = "NO_APLICA"


class BenefitIneligibilityReason(str, Enum):
    BENEFICIO_INACTIVO = "BENEFICIO_INACTIVO"
    POLITICA_NO_VIGENTE = "POLITICA_NO_VIGENTE"
    LINEA_NO_CUBIERTA = "LINEA_NO_CUBIERTA"
    DIA_NO_PERMITIDO = "DIA_NO_PERMITIDO"
    FUERA_DE_HORARIO = "FUERA_DE_HORARIO"
    DESPUES_DE_HORA_LIMITE = "DESPUES_DE_HORA_LIMITE"
    USUARIO_NO_REGISTRADO = "USUARIO_NO_REGISTRADO"
    CONTEXTO_NO_ELEGIBLE = "CONTEXTO_NO_ELEGIBLE"
    LIMITE_PERSONAS_EXCEDIDO = "LIMITE_PERSONAS_EXCEDIDO"


@dataclass(frozen=True)
class BenefitEligibilityPolicy:
    product_type: str
    benefit_line: str
    active: bool
    valid_from: str
    valid_to: Optional[str]
    allowed_weekdays: tuple[int, ...]
    allowed_time_windows: tuple[tuple[str, str], ...]
    strict_cutoff_time: Optional[str] = None
    requires_registered_user: bool = False
    requires_business_context: bool = False
    max_people: Optional[int] = None


@dataclass(frozen=True)
class BenefitEligibilityContext:
    operation_date: str
    weekday: int
    local_time: str
    requested_line: str
    registered_user: bool
    business_context: bool
    people_count: int


@dataclass(frozen=True)
class BenefitEligibilityResult:
    decision: BenefitEligibilityDecision
    reasons: tuple[BenefitIneligibilityReason, ...]


def _benefit_line_covers(policy_line: str, requested_line: str) -> bool:
    normalized_policy = str(policy_line or "").strip().upper()
    normalized_requested = str(requested_line or "").strip().upper()
    if normalized_policy == "AMBOS":
        return normalized_requested in {"ALIMENTOS", "BEBIDAS"}
    return normalized_policy == normalized_requested


def _time_in_window(local_time: str, start: str, end: str) -> bool:
    # Comparacion HH:MM lexicografica; la politica debe usar hora local canonica ya resuelta.
    if start <= end:
        return start <= local_time <= end
    # Ventana que cruza medianoche.
    return local_time >= start or local_time <= end


def evaluate_benefit_eligibility(policy: BenefitEligibilityPolicy, context: BenefitEligibilityContext) -> BenefitEligibilityResult:
    reasons = []
    if not policy.active:
        reasons.append(BenefitIneligibilityReason.BENEFICIO_INACTIVO)
    if context.operation_date < policy.valid_from or (policy.valid_to and context.operation_date > policy.valid_to):
        reasons.append(BenefitIneligibilityReason.POLITICA_NO_VIGENTE)
    if not _benefit_line_covers(policy.benefit_line, context.requested_line):
        reasons.append(BenefitIneligibilityReason.LINEA_NO_CUBIERTA)
    if policy.allowed_weekdays and context.weekday not in set(policy.allowed_weekdays):
        reasons.append(BenefitIneligibilityReason.DIA_NO_PERMITIDO)
    if policy.allowed_time_windows and not any(_time_in_window(context.local_time, start, end) for start, end in policy.allowed_time_windows):
        reasons.append(BenefitIneligibilityReason.FUERA_DE_HORARIO)
    if policy.strict_cutoff_time and context.local_time >= policy.strict_cutoff_time:
        reasons.append(BenefitIneligibilityReason.DESPUES_DE_HORA_LIMITE)
    if policy.requires_registered_user and not context.registered_user:
        reasons.append(BenefitIneligibilityReason.USUARIO_NO_REGISTRADO)
    if policy.requires_business_context and not context.business_context:
        reasons.append(BenefitIneligibilityReason.CONTEXTO_NO_ELEGIBLE)
    if policy.max_people is not None and context.people_count > policy.max_people:
        reasons.append(BenefitIneligibilityReason.LIMITE_PERSONAS_EXCEDIDO)
    return BenefitEligibilityResult(
        decision=BenefitEligibilityDecision.APLICA if not reasons else BenefitEligibilityDecision.NO_APLICA,
        reasons=tuple(reasons),
    )
